--
-- Table structure for table `examgroup`
--

DROP TABLE IF EXISTS `examgroup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `examgroup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instituteId` int(11) NOT NULL,
  `academicYearId` int(11) NOT NULL,
  `classId` int(11) NOT NULL,
  `name` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `startDate` datetime(3) DEFAULT NULL,
  `endDate` datetime(3) DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'DRAFT',
  `releasedAt` datetime(3) DEFAULT NULL,
  `releasedBy` int(11) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `examgroup_instituteId_idx` (`instituteId`),
  KEY `examgroup_academicYearId_idx` (`academicYearId`),
  KEY `examgroup_classId_idx` (`classId`),
  KEY `examgroup_releasedBy_fkey` (`releasedBy`),
  CONSTRAINT `examgroup_academicYearId_fkey` FOREIGN KEY (`academicYearId`) REFERENCES `academicyear` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `examgroup_classId_fkey` FOREIGN KEY (`classId`) REFERENCES `class` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `examgroup_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `examgroup_releasedBy_fkey` FOREIGN KEY (`releasedBy`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

