INSERT INTO `feature` VALUES (1,'ATTENDANCE','Daily Attendance Tracking','Academic','Student and teacher daily digital attendance marking & SMS alerts'),(2,'TIMETABLE','Class Timetables & Schedules','Academic','Interactive timetable matrix and room allocation scheduler'),(3,'ASSIGNMENTS','Homework & Assignments','Academic','Digital assignment creation, student submissions, and grading'),(4,'ONLINE_EXAMS','Online Computer-Based Exams','Academic','Automated MCQ exams with timer and instant result calculation'),(5,'WRITTEN_EXAMS','Term & Written Exams','Academic','Custom examination structures, marks entry, and GPA computation'),(6,'BULK_MARK_ENTRY','Bulk Marks Entry Sheet','Academic','Fast spreadsheet-style marks entry for entire batches'),(7,'PDF_REPORTS','PDF Report Cards & Transcripts','Academic','Customizable branded academic report cards and student profiles'),(8,'CSV_EXPORT','CSV & Excel Data Export','Academic','One-click full dataset exports for offline reporting'),(9,'LMS','Learning Management System (LMS)','Learning','Video lessons, study modules, and structured digital curriculums'),(10,'COURSES','Online Courses & Materials','Learning','Course management, PDF notes, and downloadable study kits'),(11,'ZOOM_CLASSES','Live Zoom / Online Classes','Learning','One-click live classroom meetings and session recording links'),(12,'FEES','Fee Structures & Collections','Finance','Tuition fees, lab fees, admission fees, and installment plans'),(13,'INVOICES','Invoicing & Official Receipts','Finance','Automated billing, printable invoices, and official payment receipts'),(14,'PAYMENT_METHODS','Multiple Payment Methods','Finance','Support for cash, card, bank transfer, and gateway receipts'),(15,'INTERNAL_MESSAGES','Internal Direct Messaging','Communication','In-app secure communications between teachers, students, and admins'),(16,'ANNOUNCEMENTS','Notice Board & Announcements','Communication','Broadcast urgent circulars to specific classes or entire institute'),(17,'SUPPORT_DESK','Helpdesk & Support Tickets','Communication','In-house ticketing system for student and parent inquiries'),(18,'WHATSAPP','WhatsApp Business API Integration','Communication','Automated WhatsApp alerts for fees, attendance, and exam marks'),(19,'STUDENT_MANAGEMENT','Full Student Lifecycle Management','Engagement','Admissions, profiles, parent linkages, and transfer certificates'),(20,'TEACHER_MANAGEMENT','Faculty & Teacher Management','Engagement','Staff directory, payroll profiles, and subject assignments'),(21,'PARENT_PORTAL','Parent Guardian Portal','Engagement','Real-time parent access to marks, attendance, and fee invoices'),(22,'LIBRARY','Library & Book Issue Management','Engagement','Book inventory, barcode tracking, and overdue fine calculations'),(23,'GALLERY','Campus Photo Gallery','Engagement','Events gallery and campus activity showcase'),(24,'POLLS','Student & Staff Polls','Engagement','Interactive feedback surveys and voting polls'),(25,'MARKETING','Marketing & Admission Popups','Engagement','Promotional popups and new batch registration announcements'),(26,'ADVANCED_ANALYTICS','Advanced Performance Analytics','Advanced','Deep charts, cohort analysis, and trend projections'),(27,'CERTIFICATES','Automated Certificate Generator','Advanced','One-click course completion and achievement certificate issuance'),(28,'ID_CARDS','Student & Staff ID Card Designer','Advanced','Printable barcode-enabled student and staff identity cards'),(29,'MULTI_BRANCH','Multi-Campus / Multi-Branch','Advanced','Manage multiple physical branches under a unified master dashboard'),(30,'STUDY_MATERIALS','Study Notes & Tutes (Multi-Language)','Learning','Digital PDF notes, tutes, and materials in Tamil, English, and Sinhala');
/*!40000 ALTER TABLE `feature` ENABLE KEYS */;
UNLOCK TABLES;

