  KEY `institutereferral_referredInstituteId_idx` (`referredInstituteId`),
  KEY `institutereferral_campaignId_idx` (`campaignId`),
  KEY `institutereferral_status_idx` (`status`),
  CONSTRAINT `institutereferral_campaignId_fkey` FOREIGN KEY (`campaignId`) REFERENCES `referralcampaign` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `institutereferral_referredInstituteId_fkey` FOREIGN KEY (`referredInstituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `institutereferral_referrerInstituteId_fkey` FOREIGN KEY (`referrerInstituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
