DROP TABLE IF EXISTS `institutesubscription`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `institutesubscription` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instituteId` int(11) NOT NULL,
  `planId` int(11) DEFAULT NULL,
  `planNameSnapshot` varchar(191) NOT NULL,
  `priceSnapshot` decimal(10,2) NOT NULL,
  `currencySnapshot` varchar(191) NOT NULL DEFAULT 'LKR',
  `durationSnapshot` int(11) NOT NULL,
  `durationTypeSnapshot` enum('DAYS','MONTHS','YEARS') NOT NULL DEFAULT 'MONTHS',
  `featuresSnapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`featuresSnapshot`)),
  `limitsSnapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`limitsSnapshot`)),
  `startDate` datetime(3) DEFAULT NULL,
  `endDate` datetime(3) DEFAULT NULL,
  `status` enum('PENDING_PAYMENT','PAYMENT_SUBMITTED','ACTIVE','REJECTED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'PENDING_PAYMENT',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `institutesubscription_instituteId_idx` (`instituteId`),
  KEY `institutesubscription_status_idx` (`status`),
  KEY `institutesubscription_planId_fkey` (`planId`),
  CONSTRAINT `institutesubscription_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `institutesubscription_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `subscriptionplan` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
