DROP TABLE IF EXISTS `invoice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `invoice` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instituteId` int(11) DEFAULT 1,
  `invoiceNumber` varchar(191) NOT NULL,
  `studentId` int(11) NOT NULL,
  `classId` int(11) DEFAULT NULL,
  `title` varchar(191) NOT NULL,
  `totalAmount` double NOT NULL,
  `paidAmount` double NOT NULL DEFAULT 0,
  `dueDate` datetime(3) NOT NULL,
  `status` enum('UNPAID','PARTIALLY_PAID','PAID','OVERDUE') NOT NULL DEFAULT 'UNPAID',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_instituteId_invoiceNumber_key` (`instituteId`,`invoiceNumber`),
  KEY `invoice_instituteId_idx` (`instituteId`),
  KEY `invoice_studentId_fkey` (`studentId`),
  KEY `invoice_classId_fkey` (`classId`),
  CONSTRAINT `invoice_classId_fkey` FOREIGN KEY (`classId`) REFERENCES `class` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `invoice_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `invoice_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `student` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
