CREATE TABLE `platformannouncement` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(191) NOT NULL,
  `message` text NOT NULL,
  `priority` enum('INFO','IMPORTANT','URGENT') NOT NULL DEFAULT 'INFO',
  `targetType` enum('ALL_INSTITUTES','SELECTED_INSTITUTES') NOT NULL DEFAULT 'ALL_INSTITUTES',
  `status` enum('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  `startsAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `expiresAt` datetime(3) DEFAULT NULL,
  `createdById` int(11) NOT NULL,
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `platformannouncement_status_idx` (`status`),
  KEY `platformannouncement_startsAt_idx` (`startsAt`),
  KEY `platformannouncement_expiresAt_idx` (`expiresAt`),
  KEY `platformannouncement_createdById_idx` (`createdById`),
  CONSTRAINT `platformannouncement_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
