--
-- Table structure for table `pollvote`
--

DROP TABLE IF EXISTS `pollvote`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pollvote` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pollId` int(11) NOT NULL,
  `optionId` int(11) NOT NULL,
  `userId` int(11) NOT NULL,
  `instituteId` int(11) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pollvote_pollId_userId_key` (`pollId`,`userId`),
  KEY `pollvote_pollId_idx` (`pollId`),
  KEY `pollvote_optionId_idx` (`optionId`),
  KEY `pollvote_userId_idx` (`userId`),
  KEY `pollvote_instituteId_idx` (`instituteId`),
  CONSTRAINT `pollvote_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pollvote_optionId_fkey` FOREIGN KEY (`optionId`) REFERENCES `polloption` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pollvote_pollId_fkey` FOREIGN KEY (`pollId`) REFERENCES `poll` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pollvote_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

