--
-- Table structure for table `resultauditlog`
--

DROP TABLE IF EXISTS `resultauditlog`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resultauditlog` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instituteId` int(11) DEFAULT 1,
  `resultId` int(11) NOT NULL,
  `examId` int(11) NOT NULL,
  `studentId` int(11) NOT NULL,
  `action` varchar(191) NOT NULL,
  `previousMarks` double DEFAULT NULL,
  `newMarks` double DEFAULT NULL,
  `previousPercentage` double DEFAULT NULL,
  `newPercentage` double DEFAULT NULL,
  `previousGrade` varchar(191) DEFAULT NULL,
  `newGrade` varchar(191) DEFAULT NULL,
  `previousPassFail` varchar(191) DEFAULT NULL,
  `newPassFail` varchar(191) DEFAULT NULL,
  `reason` text DEFAULT NULL,
  `changedBy` int(11) DEFAULT NULL,
  `changedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `resultauditlog_resultId_idx` (`resultId`),
  KEY `resultauditlog_examId_idx` (`examId`),
  KEY `resultauditlog_studentId_idx` (`studentId`),
  KEY `resultauditlog_instituteId_idx` (`instituteId`),
