  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `studymaterial_instituteId_idx` (`instituteId`),
  KEY `studymaterial_classId_idx` (`classId`),
  KEY `studymaterial_subjectId_idx` (`subjectId`),
  KEY `studymaterial_language_idx` (`language`),
  KEY `studymaterial_status_idx` (`status`),
  KEY `studymaterial_accessType_idx` (`accessType`),
  KEY `studymaterial_createdById_idx` (`createdById`),
  CONSTRAINT `studymaterial_classId_fkey` FOREIGN KEY (`classId`) REFERENCES `class` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `studymaterial_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `studymaterial_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `studymaterial_subjectId_fkey` FOREIGN KEY (`subjectId`) REFERENCES `subject` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
