  KEY `studymaterialpurchase_status_idx` (`status`),
  KEY `studymaterialpurchase_approvedAt_idx` (`approvedAt`),
  KEY `studymaterialpurchase_reviewedById_fkey` (`reviewedById`),
  CONSTRAINT `studymaterialpurchase_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `studymaterialpurchase_materialId_fkey` FOREIGN KEY (`materialId`) REFERENCES `studymaterial` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `studymaterialpurchase_reviewedById_fkey` FOREIGN KEY (`reviewedById`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `studymaterialpurchase_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `student` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
