--
-- Table structure for table `transaction`
--

DROP TABLE IF EXISTS `transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transaction` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `instituteId` int(11) DEFAULT 1,
  `transactionNumber` varchar(191) NOT NULL,
  `invoiceId` int(11) NOT NULL,
  `studentId` int(11) NOT NULL,
  `paymentMethodId` int(11) DEFAULT NULL,
  `amount` double NOT NULL,
  `paymentDate` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `receiptFile` varchar(191) DEFAULT NULL,
  `status` enum('PENDING','VERIFIED','REJECTED') NOT NULL DEFAULT 'PENDING',
  `verifiedById` int(11) DEFAULT NULL,
  `remarks` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_transactionNumber_key` (`transactionNumber`),
  KEY `transaction_instituteId_idx` (`instituteId`),
  KEY `transaction_invoiceId_fkey` (`invoiceId`),
  KEY `transaction_studentId_fkey` (`studentId`),
  KEY `transaction_paymentMethodId_fkey` (`paymentMethodId`),
  KEY `transaction_verifiedById_fkey` (`verifiedById`),
  CONSTRAINT `transaction_instituteId_fkey` FOREIGN KEY (`instituteId`) REFERENCES `institute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `transaction_invoiceId_fkey` FOREIGN KEY (`invoiceId`) REFERENCES `invoice` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `transaction_paymentMethodId_fkey` FOREIGN KEY (`paymentMethodId`) REFERENCES `paymentmethod` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `transaction_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `student` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `transaction_verifiedById_fkey` FOREIGN KEY (`verifiedById`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

